(function(root){'use strict';
root.PiraV7FixedContent={
T01:{subtitle:'必要な情報を守り、不要な情報を残し続けないために',caseTitle:'身近な例｜昔の顧客情報が残っていたら？',caseText:['何年も前に取引が終了した顧客の情報や、以前の担当者が作成したExcelファイルが、共有フォルダーに残っていることがあります。','その情報が業務上不要になっていても、外部から不正アクセスを受けたり、誤って共有したりすれば、情報漏えいの対象になる可能性があります。','※日常業務を想定した例であり、特定の事故を示すものではありません。'],pointsTitle:'情報の保管・廃棄で大切な3つのこと',points:['保存期間を決める：法令・契約・業務上の必要性を確認','保管場所を把握：紙・共有フォルダー・クラウドを確認','適切に廃棄する：紙は裁断、電子データは適切に削除'],factTitle:'豆知識｜ファイルを削除すれば安心？',fact:['パソコンのファイルを削除しても、バックアップやクラウドの共有先などにコピーが残っている場合があります。','また、機器を廃棄する際には、通常のファイル削除だけではデータを復元できる場合があるため、適切な消去方法を選ぶことが大切です。']},
T02:{subtitle:'重要な情報を、安全に相手へ届けるために',caseTitle:'身近な事例｜添付ファイルの取り違え',caseText:['2026年8月、大阪市立美術館で、メールに誤ったファイルを添付し、関係者の氏名・住所などの個人情報を別の相手に送信する事故が公表されました。','こうした事故は、サイバー攻撃を受けなくても、普段のメール業務で起こり得ます。','出典：大阪市（2026年8月19日公表、漏えい対象は1名分） https://www.city.osaka.lg.jp/hodoshiryo/keizaisenryaku/0000685813.html'],pointsTitle:'安全に情報を送るための3つのポイント',points:['送信前の確認：宛先・Cc・添付ファイルの中身を確認','共有方法の工夫：アクセス制限付きのファイル共有などを検討','送信後の対応：誤送信に気づいた際の連絡先を決めておく'],factTitle:'豆知識｜PPAPをやめれば安全？',fact:['PPAPの代わりにクラウドでファイルを共有する場合も、共有相手やアクセス権限を間違えると情報漏えいにつながります。','大切なのは、送付方法だけでなく、誰がアクセスできるか、いつまで利用できるかも管理することです。'],resource:'MAIL'},
T03:{subtitle:'情報漏えいの防止と、無駄なIT費用の削減につなげるために',caseTitle:'身近な例｜退職者のアカウントが残っていたら？',caseText:['退職した職員のメールやクラウドサービスのアカウントが残っていると、本人や第三者が情報にアクセスできる状態が続く場合があります。','例えば、顧客情報、共有フォルダー、取引先とのやり取りなど、複数の場所にアクセスできることもあります。','※具体的な業務例であり、実際の事故を紹介するものではありません。'],pointsTitle:'退職・異動時に確認したい3つのこと',points:['アカウント停止：退職後に利用できない状態にする','権限の見直し：異動前の不要なアクセス権を外す','ライセンス整理：不要な契約・利用枠を確認する'],factTitle:'豆知識｜アカウントを停止するだけで十分？（後続承認版）',fact:['アカウントを停止しても、共有リンクや外部サービスへのアクセス権などが別に残る場合があります。','そのため、どのサービスを利用していたかを一覧で把握し、必要な停止・変更を確認することが大切です。','ページ下部でご紹介している「退職・異動時のアカウント確認表」を活用すると、利用サービスや対応状況を一覧で整理できます。'],resource:'ACCOUNT'},
T04:{subtitle:'パスワードが知られても、不正ログインを防ぎやすくするために',caseTitle:'身近な例｜パスワードが盗まれたら？',caseText:['偽のログイン画面にメールアドレスとパスワードを入力してしまった場合、攻撃者がその情報を使ってログインを試みることがあります。','多要素認証を設定していれば、パスワードだけではログインできない仕組みにできます。ただし、偽サイトに認証コードまで入力してしまう攻撃などもあるため、万能ではありません。'],pointsTitle:'多要素認証で知っておきたい3つのこと',points:['パスワード以外で確認：認証アプリや生体認証などを組み合わせる','不審な要求を承認しない：身に覚えのない通知は承認しない','重要なサービスから確認：メールや業務用クラウドの設定を確認する'],factTitle:'豆知識｜認証アプリを使えば絶対安全？',fact:['多要素認証にもさまざまな方式があります。認証コードを入力する方式は、偽サイトにコードを入力してしまう危険があります。','一方、パスキーなどの仕組みは、偽サイトへのログインを防ぎやすい特徴があります。利用できるサービスでは、こうした方式も選択肢になります。'],resource:'EDUCATION',resourceText:'多要素認証は、仕組みを導入するだけでなく、利用する職員が注意点を知っておくことも大切です。ページ下部の「職員向け情報セキュリティ教育資料」も、日常の確認にお役立てください。'},
T05:{subtitle:'パソコンの弱点を放置せず、安全に使い続けるために',caseTitle:'身近な例｜更新していないパソコンが残っていたら？',caseText:['普段あまり使わないパソコンや、担当者が変わったパソコンは、更新状況が確認されないまま残ることがあります。','こうした端末に既知の脆弱性が残っていると、攻撃に悪用される可能性があります。普段使っている端末だけでなく、組織全体で確認することが大切です。','※日常業務を想定した例であり、特定の事故を示すものではありません。'],pointsTitle:'OS更新で大切な3つのこと',points:['定期的に更新：更新を後回しにせず、適用状況を確認する','対象を把握：普段使わない端末も含めて確認する','期限を確認：OSのサポート終了時期を把握する'],factTitle:'豆知識｜更新していれば絶対に安全？',fact:['更新プログラムは、知られている弱点への対策として重要ですが、すべての攻撃を防げるわけではありません。','不審なメールへの注意、適切なアクセス権限、バックアップなど、ほかの対策と組み合わせることが大切です。'],resource:'CALENDAR',resourceText:'パソコンの更新は、一度確認して終わりではなく、継続することが大切です。ページ下部の「情報管理・セキュリティ年間確認カレンダー」も、定期的な確認にお役立てください。'},
T07:{subtitle:'いつもの取引先からの連絡でも、確認が必要な理由',caseTitle:'身近な例｜いつもの取引先から「振込先が変わりました」',caseText:['毎月取引している会社の担当者から、次のようなメールが届いたとします。','「今月から振込先口座が変更になりました。請求書に記載の新しい口座へお振り込みください。」','差出人名や署名がいつもと同じでも、メールアカウントが乗っ取られていたり、送信元が偽装されていたりする可能性があります。','※詐欺の仕組みを説明するための架空の例です。'],pointsTitle:'被害を防ぐための3つの確認',points:['別の方法で確認：以前から把握している電話番号へ連絡','変更内容を照合：口座名義・金融機関・支店などを確認','社内で共有：経理担当者だけで判断せず、変更手順に沿って処理'],factTitle:'豆知識｜メールに返信して確認すれば大丈夫？',fact:['攻撃者が取引先のメールアカウントを乗っ取っている場合、返信先も攻撃者が操作している可能性があります。','そのため、届いたメールに返信するのではなく、以前から登録している電話番号など、独立した連絡手段で確認することが重要です。']},
T08:{subtitle:'万一の事故で、被害を広げず適切に対応するために',caseTitle:'身近な例｜顧客情報を間違った相手に送ってしまったら？',caseText:['担当者が顧客情報を含むファイルを、誤った宛先へメール送信してしまったとします。','誰に報告すればよいか分からず対応が遅れると、送信先への削除依頼や関係者への連絡など、必要な対応の開始も遅れてしまいます。','※初動対応を説明するための架空の例です。'],pointsTitle:'事故が起きたときに大切な3つのこと',points:['すぐに連絡：決められた担当者へ速やかに報告','被害拡大を防ぐ：担当者の指示で必要な初動対応を行う','経緯を記録：発見時刻・対応内容・連絡先を残す'],factTitle:'豆知識｜事故の記録は、なぜ必要？',fact:['事故が起きると、複数の担当者が同時に対応することがあります。誰が何を確認したか分からなくなると、対応漏れや重複が起きる可能性があります。','発見した時刻、確認した事実、連絡した相手、実施した対応を時系列で残すことで、状況の共有や原因調査にも役立ちます。','こうした記録を残すために、ページ下部の「情報漏洩・紛失時の初動対応キット」を活用できます。'],resource:'INCIDENT'}
};
})(globalThis);
